import { useRef } from "react";

export function Composer() {
  // "Saves re-renders", and freezes everything that shows the text
  const textRef = useRef("");
  const length = textRef.current.length; // read during render: stale

  return (
    <>
      <textarea onChange={(e) => { textRef.current = e.target.value; }} />
      <span>{length}/280</span>
      <button disabled={length === 0}>Post</button>
    </>
  );
}

import { useState } from "react";

export function Composer() {
  // Shown on screen, so it's state: every keystroke updates the counter
  const [text, setText] = useState("");

  return (
    <>
      <textarea value={text} onChange={(e) => setText(e.target.value)} />
      <span>{text.length}/280</span>
      <button disabled={text.length === 0}>Post</button>
    </>
  );
}

