import { useRef, useState } from "react";

export function SearchBox({ onSearch }: { onSearch: (q: string) => void }) {
  const [query, setQuery] = useState(""); // shown on screen: state
  const timerRef = useRef<number | undefined>(undefined); // never shown: ref

  function handleChange(next: string) {
    setQuery(next);
    clearTimeout(timerRef.current); // cancel the search still pending
    timerRef.current = window.setTimeout(() => onSearch(next), 300);
  }

  return <input value={query} onChange={(e) => handleChange(e.target.value)} />;
}
